Contract LibraryManagementSystemSystem::countDownSuspensionDay() {

            precondition:
          true

            postcondition:
          User.allInstances()->forAll(u:User|true = true and u.UserID = u.UserID@pre and u.Name = u.Name@pre and u.Sex = u.Sex@pre and u.Password = u.Password@pre and u.Email = u.Email@pre and u.Faculty = u.Faculty@pre and u.LoanedNumber = u.LoanedNumber@pre and u.OverDueFee = u.OverDueFee@pre and if u.SuspensionDays@pre > 0 then u.SuspensionDays = u.SuspensionDays@pre - 1 else u.SuspensionDays = u.SuspensionDays@pre endif and if u.BorrowStatus@pre = BorrowStatus::SUSPEND and u.SuspensionDays@pre = 1 and u.OverDueFee@pre = 0.0 then u.BorrowStatus = BorrowStatus::NORMAL else u.BorrowStatus = u.BorrowStatus@pre endif)

        }
